using System;using Ossastra.CharacterCore;
class ChainTests{static int n;static void C(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);n++;}static void Main(){var c=new BasicChainState(.12,.17,.45);var id=Guid.NewGuid();C(c.Request(0,true,true)==1,"first explicit request");c.Accepted(1,id,0,.8);C(c.Poll(.8,true)==0,"no automatic stage2");C(c.Request(.4,false,true)==0&&!c.HasBuffer,"too early discarded");c.Hit(id,true);C(c.Request(.7,false,true)==0&&c.HasBuffer,"one preinput");C(c.Request(.71,false,true)==0&&c.HasBuffer,"repeat does not add");C(c.Poll(.8,true)==2&&!c.HasBuffer,"buffer consumes once");C(c.Poll(.81,true)==0,"no second consume");c.Accepted(2,Guid.NewGuid(),.8,.9);C(c.Request(1.7,true,true)==1,"stage2 ends chain");c.Accepted(1,id,2,.8);c.Hit(id,false);C(c.Request(2.8,true,true)==1,"miss restarts stage1");c.Accepted(1,id,3,.8);c.Hit(id,true);C(c.Request(4.3,true,true)==1,"expired window restarts");c.Accepted(1,id,5,.8);c.Hit(id,true);c.Request(5.7,false,true);C(c.Poll(6,true)==0&&!c.HasBuffer,"expired buffer discarded");c.Accepted(1,id,7,.8);c.Hit(Guid.NewGuid(),true);C(c.Request(7.8,true,true)==1,"foreign receipt cannot grant stage2");c.Accepted(1,id,8,.8);c.Hit(id,true);c.Request(8.7,false,true);c.Clear();C(c.Poll(8.8,true)==0,"control loss clears buffer");C(c.Request(9,true,false)==0,"ineligible cannot attack");Console.WriteLine(n+" chain contracts passed");}}
